import type { ApiPath, ApiRequest, ApiResponse } from '../types/api';

export interface RetryOptions {
  maxRetries: number;
  backoff: 'linear' | 'exponential';
  baseDelayMs?: number;
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function retryWithBackoff<T>(request: () => Promise<T>, options: RetryOptions): Promise<T> {
  const baseDelayMs = options.baseDelayMs ?? 200;
  let attempt = 0;
  for (;;) {
    try {
      return await request();
    } catch (error) {
      attempt += 1;
      if (attempt > options.maxRetries) throw error;
      const delay = options.backoff === 'exponential' ? baseDelayMs * 2 ** (attempt - 1) : baseDelayMs * attempt;
      await sleep(delay);
    }
  }
}

/**
 * `RequestInit` for a route, with `body` replaced by that route's request type. Routes without a
 * request body of their own cannot pass one; everything else (headers, signal, method) is unchanged.
 */
export type ApiRequestInit<P extends ApiPath> = Omit<RequestInit, 'body'> &
  ([ApiRequest<P>] extends [never] ? { body?: never } : { body: ApiRequest<P> });

/** `init` is optional for routes that take no body, and required for the ones that do. */
type ApiFetchInit<P extends ApiPath> = [ApiRequest<P>] extends [never]
  ? [init?: ApiRequestInit<P>]
  : [init: ApiRequestInit<P>];

export async function apiFetch<P extends ApiPath>(
  path: P,
  ...[init]: ApiFetchInit<P>
): Promise<ApiResponse<P>> {
  return retryWithBackoff(async () => {
    const { body, headers, ...rest } = init ?? {};
    const response = await fetch(`/api${path}`, {
      ...rest,
      headers: body === undefined ? headers : { 'content-type': 'application/json', ...headers },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
    return (await response.json()) as ApiResponse<P>;
  }, { maxRetries: 3, backoff: 'exponential' });
}

/**
 * Wire types for the Express API in `server/routes.ts`.
 *
 * These are deliberately standalone declarations rather than imports from `server/`: the client
 * talks to the API over JSON, so it should depend on the wire format and not on server modules.
 * Every field here is already JSON-safe (dates are ISO strings), so the redeclaration is lossless.
 */

export type UserRole = 'admin' | 'member' | 'viewer';
export type SubscriptionPlan = 'starter' | 'team' | 'enterprise';
export type SubscriptionStatus = 'active' | 'past_due' | 'cancelled';

export interface Subscription {
  id: string;
  userId: string;
  plan: SubscriptionPlan;
  status: SubscriptionStatus;
  renewsAt: string;
}

export interface Invoice {
  id: string;
  userId: string;
  amountCents: number;
  issuedAt: string;
  paid: boolean;
}

/**
 * The body every route sends on a non-2xx response (401, 429). `apiFetch` rejects on those, so
 * this shape is never part of a route's resolved response type.
 */
export interface ApiError {
  error: string;
}

/** `POST /api/login` */
export interface LoginRequest {
  email: string;
  password: string;
}

export interface LoginResponse {
  token: string;
}

/** `GET /api/me` — the claims the server exposes, with `sub` renamed to `id`. */
export interface MeResponse {
  id: string;
  role: UserRole;
}

/** `GET /api/subscriptions` */
export type SubscriptionsResponse = Subscription[];

/** `GET /api/invoices` */
export type InvoicesResponse = Invoice[];

/** `POST /api/subscriptions/:id/cancel` — responds with the updated subscription. */
export type CancelSubscriptionResponse = Subscription;

/** A path with no request body of its own. */
export type NoRequestBody = never;

/**
 * Every route the API exposes, keyed by the path passed to `apiFetch` (the `/api` prefix is added
 * by the client). The `:id` route is matched by a template-literal key, so
 * `/subscriptions/sub_501/cancel` resolves just like the literal paths do.
 */
export interface ApiRoutes {
  '/login': { request: LoginRequest; response: LoginResponse };
  '/me': { request: NoRequestBody; response: MeResponse };
  '/subscriptions': { request: NoRequestBody; response: SubscriptionsResponse };
  '/invoices': { request: NoRequestBody; response: InvoicesResponse };
  [path: `/subscriptions/${string}/cancel`]: {
    request: NoRequestBody;
    response: CancelSubscriptionResponse;
  };
}

export type ApiPath = keyof ApiRoutes;

export type ApiRequest<P extends ApiPath> = ApiRoutes[P]['request'];

export type ApiResponse<P extends ApiPath> = ApiRoutes[P]['response'];
